// Tablero de Control Contable y Auditoría v3 – 6 tarjetas, pensado primero para celular.
// Regla general: solo se muestran acciones hechas por el estudio. Nunca nombres, CUIT completo ni claves.
const leer = (n) => { try { return $(n).all().map(i => i.json); } catch (e) { return []; } };
const vacio = (r) => Object.keys(r).length === 0;
const carga = leer('Leer Carga Operativa').filter(r => r.ID_Empresa !== undefined && r.ID_Empresa !== '');
const hist = leer('Leer Historico').filter(r => r.fecha_hora !== undefined && r.fecha_hora !== '');
const bal = leer('Leer Balances').filter(r => r.CUIT);
const doc = leer('Leer Documentacion Balances').filter(r => r.CUIT);
const sue = leer('Leer Sueldos').filter(r => r.CUIT);
const ins = leer('Leer Inspecciones').filter(r => r.codigo_inspeccion);
const mono = leer('Leer Monotributos').filter(r => r.CUIT);
const cal = leer('Leer Calendario ARCA').filter(r => r.impuesto);
const ult = hist.length ? hist[hist.length - 1] : {};
const HOY = $now.setZone('America/Argentina/Buenos_Aires').toFormat('yyyy-MM-dd');

// ---------- utilidades ----------
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const si = (v) => String(v || '').trim().toLowerCase().replace('í', 'i') === 'si';
const p2 = (n) => String(n).padStart(2, '0');
const iso = (v) => {
  if (typeof v === 'number') { const d = new Date(Math.round((v - 25569) * 86400000)); return d.getUTCFullYear() + '-' + p2(d.getUTCMonth() + 1) + '-' + p2(d.getUTCDate()); }
  const s = String(v || '').replace(/^'/, '').trim();
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return m[3] + '-' + p2(m[2]) + '-' + p2(m[1]);
  return s.slice(0, 10);
};
const dmy = (v) => { const s = iso(v); return s.length === 10 ? s.slice(8, 10) + '/' + s.slice(5, 7) + '/' + s.slice(0, 4) : '-'; };
const fmtHora = (v) => {
  if (typeof v === 'number') { const d = new Date(Math.round((v - 25569) * 86400000)); return p2(d.getUTCDate()) + '/' + p2(d.getUTCMonth() + 1) + '/' + d.getUTCFullYear() + ' ' + p2(d.getUTCHours()) + ':' + p2(d.getUTCMinutes()); }
  return v ? String(v) : '-';
};
const pct = (a, b) => b ? Math.round((a / b) * 100) : null;

// Código de cliente: 3 letras del apellido o razón social + últimos 4 dígitos del CUIT (duplicados: b, c...)
const codigos = {}; const usados = {};
const codigo = (nombre, cuit) => {
  const dig = String(cuit || '').replace(/\D/g, '');
  if (codigos[dig]) return codigos[dig];
  let letras = String(nombre || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z]/g, '').slice(0, 3);
  if (letras.length < 3) letras = (letras + 'xxx').slice(0, 3);
  let c = letras + dig.slice(-4);
  if (usados[c]) { usados[c]++; c = c + String.fromCharCode(96 + usados[c]); } else { usados[c] = 1; }
  codigos[dig] = c; return c;
};

// Color en degradé según % pendiente: 0 verde flúor, 25 verde claro, 50 amarillo, 75 naranja, 100 rojo
const STOPS = [[0, [57, 255, 20]], [25, [156, 204, 101]], [50, [253, 216, 53]], [75, [251, 140, 0]], [100, [229, 57, 53]]];
const color = (p) => {
  if (p == null) return '#bdbdbd';
  for (let i = 1; i < STOPS.length; i++) {
    if (p <= STOPS[i][0]) {
      const a = STOPS[i - 1], b = STOPS[i], t = (p - a[0]) / (b[0] - a[0]);
      const c = a[1].map((x, k) => Math.round(x + (b[1][k] - x) * t));
      return 'rgb(' + c.join(',') + ')';
    }
  }
  return 'rgb(229,57,53)';
};
const estado = (p) => p == null ? 'Sin datos todavía' : (p === 0 ? 'Al día' : (p <= 25 ? 'Casi listo' : (p <= 50 ? 'En marcha' : (p <= 75 ? 'Atrasado' : 'Crítico'))));

let gid = 0;
const vaso = (p, tam) => {
  gid++;
  const h = 120, top = 20, fondo = 112, alto = fondo - top;
  const nivel = p == null ? 0 : Math.max(0, Math.min(100, p));
  const y = top + alto * (1 - nivel / 100);
  const col = color(p);
  const w = tam || 74;
  const interior = 'M16 12 L74 12 L74 106 Q74 112 68 112 L22 112 Q16 112 16 106 Z';
  const marcas = [25, 50, 75].map(m => { const ym = top + alto * (1 - m / 100); return '<line x1="54" y1="' + ym + '" x2="74" y2="' + ym + '" stroke="#5d5d5d" stroke-width="1.5"/><line x1="64" y1="' + (ym - alto / 8) + '" x2="74" y2="' + (ym - alto / 8) + '" stroke="#8a8a8a" stroke-width="1"/>'; }).join('');
  return '<svg class="vaso" width="' + w + '" viewBox="0 0 90 ' + h + '" aria-hidden="true">' +
    '<defs><clipPath id="c' + gid + '"><path d="' + interior + '"/></clipPath></defs>' +
    '<path d="' + interior + '" fill="rgba(255,255,255,.55)"/>' +
    '<g clip-path="url(#c' + gid + ')">' +
    (p == null ? '<rect x="0" y="0" width="90" height="' + h + '" fill="#eeeeee"/>' :
      '<g class="ola"><path fill="' + col + '" fill-opacity=".85" d="M-90 ' + y + ' Q-67 ' + (y - 4) + ' -45 ' + y + ' T0 ' + y + ' T45 ' + y + ' T90 ' + y + ' T135 ' + y + ' T180 ' + y + ' V' + (h + 10) + ' H-90 Z"/></g>') +
    '</g>' + marcas +
    '<path d="M6 6 Q10 12 16 12 L16 106 Q16 112 22 112 L68 112 Q74 112 74 106 L74 12 Q78 12 80 8" fill="none" stroke="#5d5d5d" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>' +
    '<line x1="22" y1="20" x2="22" y2="100" stroke="#ffffff" stroke-opacity=".7" stroke-width="3" stroke-linecap="round"/>' +
    '</svg>';
};
const nube = (txt) => '<div class="nube">&#9729; <b>Falta definir:</b> ' + esc(txt) + '</div>';
const supuesto = (txt) => '<div class="supuesto">Supuesto para la maqueta: ' + esc(txt) + '</div>';
const alerta = (txt) => '<div class="alerta">&#9888; ' + esc(txt) + '</div>';
const mini = (titulo, p, detalle) => '<div class="mini">' + vaso(p, 44) + '<div class="mtit">' + esc(titulo) + '</div><div class="mpct">' + (p == null ? '-' : p + '% pend.') + '</div>' + (detalle ? '<div class="mdet">' + esc(detalle) + '</div>' : '') + '</div>';
const flecha = '<div class="flecha">&#8594;</div>';
const lista = (titulo, items) => '<h4>' + esc(titulo) + '</h4>' + (items.length ? '<ul>' + items.map(t => '<li>' + t + '</li>').join('') + '</ul>' : '<p class="ok">Nada pendiente.</p>');
const proxVto = (filtro) => cal.filter(filtro).map(r => {
  const fechas = ['ARCA', 'AGIP', 'ARBA'].map(k => ({ org: k, f: iso(r[k]) })).filter(x => x.f && x.f.length === 10);
  const tv = r.terminacion_cuit; let term = tv;
  if (typeof tv === "number") { const d = new Date(Math.round((tv - 25569) * 86400000)); term = (d.getUTCMonth() + 1) + "-" + d.getUTCDate(); }
  return fechas.map(x => ({ imp: r.impuesto, term: term, org: x.org, f: x.f }));
}).flat().filter(x => x.f >= HOY).sort((a, b) => a.f < b.f ? -1 : 1);

// ---------- 1. IMPUESTOS ----------
const imp = (() => {
  if (!carga.length) return null;
  const num = (v) => (v === '' || v == null) ? 3 : Number(v);
  const finCarga = (r) => String(r.Estado_Carga || '').toUpperCase().indexOf('FINALIZ') >= 0;
  const cod = (r) => r.CUIT ? codigo('emp', r.CUIT) : 'empresa' + r.ID_Empresa;
  const presPend = carga.filter(r => num(r.ESTADO_GENERAL) !== 1);
  const cargaPend = carga.filter(r => !finCarga(r));
  const monoEnv = mono.filter(r => si(r.envia_vep));
  const monoPend = monoEnv.filter(r => !si(r.vep_enviado));
  const total = carga.length + monoEnv.length;
  const pend = presPend.length + monoPend.length;
  const p = pct(pend, total);
  const incons = carga.filter(r => num(r.ESTADO_GENERAL) !== 3 && !finCarga(r));
  const vtos = proxVto(r => ['IVA', 'IIBB', 'Monotributo'].indexOf(String(r.impuesto)) >= 0).slice(0, 4);
  const det =
    '<div class="cadena">' + mini('Carga de comprobantes', pct(cargaPend.length, carga.length), (carga.length - cargaPend.length) + '/' + carga.length + ' cargados') + flecha +
    mini('Presentación en ARCA', pct(presPend.length, carga.length), (carga.length - presPend.length) + '/' + carga.length + ' presentados') + '</div>' +
    incons.map(r => alerta(cod(r) + ': presentación avanzada con la carga sin terminar')).join('') +
    lista('Pendientes de carga (' + cargaPend.length + ')', cargaPend.map(r => '<b>' + esc(cod(r)) + '</b>')) +
    lista('Pendientes de presentación (' + presPend.length + ')', presPend.map(r => '<b>' + esc(cod(r)) + '</b> · ' + (num(r.ESTADO_GENERAL) === 2 ? 'en proceso' : 'sin comenzar') + (finCarga(r) ? ' · carga lista' : ''))) +
    lista('Monotributos: VEP sin enviar (' + monoPend.length + ' de ' + monoEnv.length + ')', monoPend.map(r => '<b>' + esc(codigo(r.apellido, r.CUIT)) + '</b> · cat. ' + esc(r.categoria))) +
    '<h4>Alertas de la IA (último control)</h4><p>' + esc(ult.cantidad_alertas != null ? ult.cantidad_alertas + ' alertas · riesgo ' + (ult.nivel_riesgo_predominante || '-') : 'Sin control registrado') + '</p>' +
    (ult.resumen_claude ? '<p class="ia">' + esc(String(ult.resumen_claude).slice(0, 600)) + '</p>' : '') +
    lista('Próximos vencimientos', vtos.map(v => esc(v.imp) + ' (term. ' + esc(v.term) + ') · ' + v.org + ' · <b>' + dmy(v.f) + '</b>'));
  return { p, sub: pend + ' de ' + total + ' clientes sin presentar', det };
})();

// ---------- 3. SUELDOS ----------
const PASOS_S = [['novedades_recibidas', 'Novedades recibidas'], ['liquidacion_hecha', 'Liquidación hecha'], ['asiento_generado', 'Asiento generado'], ['f931_presentado', 'F931 presentado'], ['vep_enviado', 'VEP enviado']];
const sueldos = (() => {
  if (!sue.length) return null;
  const t = sue.length;
  const pend = sue.filter(r => !si(r.vep_enviado));
  const periodo = sue[0].periodo ? String(sue[0].periodo).replace(/^'/, '') : '';
  const cod = (r) => codigo(r.apellido_razon_social, r.CUIT);
  const cadena = PASOS_S.map((ps, i) => mini(ps[1], pct(sue.filter(r => !si(r[ps[0]])).length, t))).join(flecha);
  const incons = [];
  sue.forEach(r => { for (let i = 1; i < PASOS_S.length; i++) { if (si(r[PASOS_S[i][0]]) && !si(r[PASOS_S[i - 1][0]])) incons.push(cod(r) + ': "' + PASOS_S[i][1] + '" marcado sin "' + PASOS_S[i - 1][1] + '"'); } });
  const pasoActual = (r) => { for (let i = 0; i < PASOS_S.length; i++) { if (!si(r[PASOS_S[i][0]])) return 'falta: ' + PASOS_S[i][1].toLowerCase(); } return ''; };
  const vto = proxVto(r => String(r.impuesto).indexOf('F931') >= 0)[0];
  const det = '<div class="cadena cinco">' + cadena + '</div>' + incons.map(alerta).join('') +
    lista('Clientes con VEP sin enviar (' + pend.length + ')', pend.map(r => '<b>' + esc(cod(r)) + '</b> · ' + esc(pasoActual(r)) + ' · ' + esc(r.responsable || 'sin responsable'))) +
    '<h4>Próximo vencimiento F931</h4><p>' + (vto ? 'Terminación ' + esc(vto.term) + ' · <b>' + dmy(vto.f) + '</b>' : 'Sin fecha cargada') + '</p>' +
    nube('cómo incluir las liquidaciones de empleadas domésticas.');
  return { p: pct(pend.length, t), sub: pend.length + ' de ' + t + ' VEP sin enviar', titulo: 'Sueldos' + (periodo ? ' – período ' + periodo : ''), det };
})();

// ---------- 4. BALANCES ----------
const PASOS_B = [['prebalance', 'Prebalance'], ['formato_legal', 'Formato legal'], ['legalizado', 'Legalizado'], ['subido_arca', 'Subido a ARCA']];
const MESES = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
const balances = (() => {
  if (!bal.length) return null;
  const cod = (r) => codigo(r.razon_social, r.CUIT);
  const grado = (r) => {
    const ds = doc.filter(d => String(d.CUIT) === String(r.CUIT) && String(d.ejercicio) === String(r.ejercicio));
    const ap = ds.filter(d => String(d.estado).toLowerCase() !== 'no aplica');
    if (!ap.length) return null;
    const pts = ap.reduce((s, d) => s + (String(d.estado).toLowerCase() === 'recibido' ? 1 : (String(d.estado).toLowerCase() === 'parcial' ? 0.5 : 0)), 0);
    return Math.round((pts / ap.length) * 100);
  };
  const cerrados = bal.filter(r => iso(r.fecha_cierre) && iso(r.fecha_cierre) < HOY);
  const pend = cerrados.filter(r => !si(r.subido_arca));
  const incons = [];
  bal.forEach(r => { for (let i = 1; i < PASOS_B.length; i++) { if (si(r[PASOS_B[i][0]]) && !si(r[PASOS_B[i - 1][0]])) incons.push(cod(r) + ': "' + PASOS_B[i][1] + '" marcado sin "' + PASOS_B[i - 1][1] + '"'); } });
  const linea = MESES.map((m, i) => {
    const rs = bal.filter(r => Number(r.mes_cierre) === i + 1);
    if (!rs.length) return '<div class="mes"><span class="pt vacio"></span>' + m + '</div>';
    const abierto = rs.every(r => !(iso(r.fecha_cierre) < HOY));
    const listo = rs.every(r => si(r.subido_arca));
    const cls = abierto ? 'futuro' : (listo ? 'listo' : 'pend');
    return '<div class="mes"><span class="pt ' + cls + '">' + rs.length + '</span>' + m + '</div>';
  }).join('');
  const paso = (r) => { for (let i = 0; i < PASOS_B.length; i++) { if (!si(r[PASOS_B[i][0]])) return 'falta: ' + PASOS_B[i][1].toLowerCase(); } return ''; };
  const det = '<h4>Cierres del año</h4><div class="linea">' + linea + '</div><div class="ley"><span class="pt listo"></span>terminado <span class="pt pend"></span>pendiente <span class="pt futuro"></span>todavía no cerró</div>' +
    '<div class="cadena">' + PASOS_B.map(ps => mini(ps[1], pct(cerrados.filter(r => !si(r[ps[0]])).length, cerrados.length))).join(flecha) + '</div>' +
    incons.map(alerta).join('') +
    lista('Balances cerrados y pendientes (' + pend.length + ')', pend.map(r => {
      const g = grado(r);
      return '<b>' + esc(cod(r)) + '</b> · cierre ' + dmy(r.fecha_cierre) + ' · ' + esc(paso(r)) + ' · ' + esc(r.responsable || '') +
        '<div class="barra"><span style="width:' + (g || 0) + '%"></span></div><small>Documentación recibida: ' + (g == null ? 'sin datos' : g + '%') + ' · vence ' + dmy(r.fecha_limite) + '</small>';
    })) +
    supuesto('la lista de documentos para el balance (extractos, ventas extraordinarias, retenciones, etc.) se ajusta con datos reales.');
  return { p: pct(pend.length, cerrados.length), sub: pend.length + ' de ' + cerrados.length + ' balances cerrados sin terminar', det };
})();

// ---------- 5. INSPECCIONES ----------
const inspecciones = (() => {
  if (!ins.length) return null;
  const grupos = {};
  ins.forEach(r => { (grupos[r.codigo_inspeccion] = grupos[r.codigo_inspeccion] || []).push(r); });
  const abiertas = Object.keys(grupos).filter(k => grupos[k].some(r => !si(r.hecho)));
  const puntos = abiertas.map(k => grupos[k]).flat();
  const pend = puntos.filter(r => !si(r.hecho));
  const det = abiertas.map(k => {
    const g = grupos[k], hechos = g.filter(r => si(r.hecho)).length, a = g[0];
    return '<div class="insp"><div class="ih"><b>' + esc(k) + '</b> · ' + esc(codigo(a.razon_social, a.CUIT)) + ' · ' + esc(a.organismo) + '<span>vence ' + dmy(a.fecha_limite) + '</span></div>' +
      '<div class="barra"><span style="width:' + pct(hechos, g.length) + '%"></span></div><small>' + hechos + ' de ' + g.length + ' puntos hechos</small>' +
      '<ul>' + g.filter(r => !si(r.hecho)).map(r => '<li>' + esc(r.punto) + ' · ' + esc(r.responsable) + '</li>').join('') + '</ul></div>';
  }).join('') || '<p class="ok">No hay inspecciones abiertas.</p>';
  return { p: pct(pend.length, puntos.length), sub: abiertas.length + ' inspecciones abiertas · ' + pend.length + ' puntos pendientes', det };
})();

// ---------- tarjetas ----------
const tarjetas = [
  { n: 1, titulo: 'Impuestos', ritmo: 'Mensual', d: imp },
  { n: 2, titulo: 'Legales (Actas)', ritmo: 'Trimestral', d: null, nube: 'qué actas se hacen cada trimestre y los pasos del estudio hasta terminar un acta.' },
  { n: 3, titulo: sueldos ? sueldos.titulo : 'Sueldos', ritmo: 'Mensual', d: sueldos },
  { n: 4, titulo: 'Balances', ritmo: 'Anual', d: balances },
  { n: 5, titulo: 'Inspecciones', ritmo: 'Eventual', d: inspecciones },
  { n: 6, titulo: 'Módulo reservado', ritmo: '', d: null, nube: 'qué módulo ocupa este lugar.', reservada: true },
];
const tarjetaHtml = (t) => {
  const p = t.d ? t.d.p : null;
  const frente = (t.reservada ? '<div class="nubegrande">&#9729;</div>' : vaso(p)) +
    '<div class="info"><div class="ritmo">' + esc(t.ritmo) + '</div><h2>' + esc(t.titulo) + '</h2>' +
    (t.reservada ? '<div class="est">Falta definir</div>' : '<div class="pct" style="color:' + (p == null ? '#9e9e9e' : '#333') + '">' + (p == null ? '–' : p + '%') + '<small>' + (p == null ? '' : ' pendiente') + '</small></div><div class="est"><span class="dot" style="background:' + color(p) + '"></span>' + estado(p) + '</div>') +
    (t.d ? '<div class="sub">' + esc(t.d.sub) + '</div>' : '') + '</div>';
  const detalle = '<div class="dhead">' + vaso(p, 60) + '<div><div class="ritmo">' + esc(t.ritmo) + '</div><h2>' + esc(t.titulo) + '</h2><div class="pct">' + (p == null ? 'Sin datos todavía' : p + '% pendiente') + '</div></div></div>' +
    (t.d ? t.d.det : '<p>Sin datos todavía. No se muestra ningún porcentaje inventado.</p>') + (t.nube ? nube(t.nube) : '');
  return '<button class="card' + (t.reservada ? ' reservada' : '') + '" data-n="' + t.n + '">' + frente + '</button><template id="det' + t.n + '">' + detalle + '</template>';
};

const css = [
  '*{box-sizing:border-box}body{margin:0;min-height:100vh;background:linear-gradient(to right,#bfa77f 0,#bfa77f 7%,#f5ecd9 7%,#f5ecd9 93%,#bfa77f 93%,#bfa77f 100%);font-family:Calibri,Arial,sans-serif;color:#333}header,main,footer{width:86%;max-width:none!important;margin-left:7%!important;margin-right:7%!important}',
  'header{padding:18px 16px 6px;max-width:1100px;margin:auto}h1{font-size:22px;margin:0 0 4px}',
  '.meta{font-size:13px;color:#6d6d6d}.ficticio{display:inline-block;margin-top:6px;background:#fff3cd;border:1px solid #f0d58c;border-radius:12px;padding:2px 10px;font-size:12px}',
  'main{display:grid;grid-template-columns:1fr;gap:14px;padding:14px 16px;max-width:1100px;margin:auto}',
  '@media(min-width:700px){main{grid-template-columns:1fr 1fr}}',
  '.card{display:flex;align-items:center;gap:14px;background:#fff;border:0;border-radius:18px;padding:14px 16px;box-shadow:0 2px 8px rgba(0,0,0,.08);text-align:left;cursor:pointer;font:inherit;color:inherit;width:100%}',
  '.card:active{transform:scale(.99)}.card.reservada{border:2px dashed #cfc6b0;box-shadow:none;background:#fffdf8}',
  '.info{flex:1;min-width:0}.ritmo{font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:#8a8a8a}',
  'h2{font-size:19px;margin:2px 0 4px}.pct{font-size:30px;font-weight:700}.pct small{font-size:14px;font-weight:400;color:#777}',
  '.est{font-size:14px;margin-top:2px}.dot{display:inline-block;width:11px;height:11px;border-radius:50%;margin-right:6px;vertical-align:middle;border:1px solid rgba(0,0,0,.15)}',
  '.sub{font-size:13px;color:#666;margin-top:4px}.nubegrande{font-size:64px;color:#cfc6b0;width:74px;text-align:center}',
  '.ola{animation:ola 4s linear infinite}@keyframes ola{from{transform:translateX(0)}to{transform:translateX(90px)}}',
  '#velo{position:fixed;inset:0;background:rgba(30,30,30,.6);display:none;align-items:center;justify-content:center;padding:12px;z-index:9}',
  '#velo.abierto{display:flex}#caja{background:#fff;border-radius:18px;max-width:640px;width:100%;max-height:90vh;overflow:auto;padding:18px;position:relative}',
  '#cerrar{position:absolute;top:8px;right:10px;border:0;background:#eee;border-radius:50%;width:34px;height:34px;font-size:18px;cursor:pointer}',
  '.dhead{display:flex;gap:12px;align-items:center;margin-bottom:8px}.dhead .pct{font-size:20px}',
  'h4{margin:14px 0 6px;font-size:15px}ul{margin:0;padding-left:18px}li{margin:4px 0;font-size:14px}.ok{color:#2e7d32;font-size:14px}',
